slides=[]
def add(title,tag,body,segments,cls='',motion=None):slides.append(dict(title=title,tag=tag,body=body,segments=segments,cls=cls,motion=motion))
def cue(cid,text):return f'<span data-cue="{cid}">{text}</span>'
cover=cv2.imread(str(P/'cover.png'));cover=cv2.resize(cover,(1920,1080))
def measured_ink(rect,orange=False):
 x,y,w,h=rect;roi=cover[y:y+h,x:x+w];b,g,r=cv2.split(roi)
 mask=(r<85)&(g<85)&(b<120)
 if orange:mask|=(r>180)&(g<120)&(b<100)
 points=cv2.findNonZero(mask.astype(np.uint8));assert points is not None
 ix,iy,iw,ih=cv2.boundingRect(points);return [x+ix,y+iy,iw,ih]
cover_boxes={'cover-title':measured_ink([100,675,1130,155],True),'cover-author':measured_ink([435,120,610,55])}
cover_targets=''.join(f'<div class="invisible" data-cue="{cid}" style="left:{x}px;top:{y}px;width:{w}px;height:{h}px"></div>' for cid,(x,y,w,h) in cover_boxes.items())
add('Claude Agent SDK','FREE COURSE','<img class="full" src="cover.png">'+cover_targets,[('cover-title','Build your first Claude Agent SDK application'),('cover-author','with Luis Coco Enriquez.')],'cover')
groups=[('1–2','SDK foundations','What is the SDK? · Getting Started'),('3–4','Your first query()','Send a task · Invoke query()'),('5–6','The agent loop','Follow decisions · Practical loop example'),('7–8','Message types','Read SDK messages · Practical example'),('9–10','Context and compaction','Understand context · Practical example'),('11–13','Configure and control','Options · Models and effort · Turns and spending')]
cards=''.join(f'<article class="index-card"><small>LECTURES {a}</small><div data-cue="index-{i}"><h2>{b}</h2><p>{c}</p></div></article>' for i,(a,b,c) in enumerate(groups))
index_phrases=['Thirteen core lectures pair SDK foundations,','query,','the agent loop,','messages,','and context with practical examples.','Then configure models, effort, turns, and spending.']
add('Your course at a glance','13 CORE LECTURES · 8 PRACTICAL EXAMPLES · 2 SECTIONS','<div class="index">'+cards+'</div><div class="bottom">Core concepts paired with practical applications</div>',[(f'index-{i}',t) for i,t in enumerate(index_phrases)])
concepts=[
 ('Start with a runnable project','LECTURES 1–2 · SDK FOUNDATIONS + GETTING STARTED','Understand the SDK','Embed the agent loop and tools in your own application.','Prepare the first example','Install the package, configure authentication, and choose a small workspace.','npm install @anthropic-ai/claude-agent-sdk\n\nimport { query } from\n  "@anthropic-ai/claude-agent-sdk";','Learn what the SDK provides, install it, and prepare a small workspace. The first example makes setup concrete.'),
 ('Send a task and follow the loop','LECTURES 3–6 · query() + AGENT LOOP','Start with one prompt','Ask a focused question that has a checkable answer.','Follow the work','The SDK yields messages while the model and tools work toward a result.','const run = query({\n  prompt: "What files are here?",\n  options: { cwd: "./sample-workspace" }\n});\nfor await (const message of run) {\n  console.log(message.type);\n}','Invoke query with a prompt and working directory. Follow its message stream as the model uses tools and produces an answer.'),
 ('Read messages and understand context','LECTURES 7–10 · MESSAGE TYPES + CONTEXT + COMPACTION','Separate progress from completion','Tool activity and assistant text are different from the final result.','Understand the working context','Learn how conversation history uses context and why compaction matters.','for await (const message of run) {\n  if (message.type === "result") {\n    console.log(message.subtype);\n  }\n}\n// History consumes context.\n// Compaction summarizes earlier history.','Distinguish progress messages from the final result. Then explore conversation context and compaction through practical examples.'),
 ('Choose how your agent runs','LECTURES 11–13 · OPTIONS + MODELS + EFFORT + LIMITS','Configure the application','Choose the model, effort and environment for the task.','Bound the experiment','Set turn and spending limits, then inspect the final outcome.','const options = {\n  cwd: "./sample-workspace",\n  allowedTools: ["Glob"],\n  maxTurns: 4,\n  maxBudgetUsd: 0.15\n};\n// Limits constrain this teaching example.','Use the options object to choose execution settings. Learn how models, effort, environment, turns, and spending limits affect your experiments.')]
for i,(title,tag,h1,p1,h2,p2,code,narration) in enumerate(concepts):
 sentences=re.split(r'(?<=\.) ',narration,maxsplit=1);assert len(sentences)==2
