add('Start building with Claude Agent SDK','YOUR NEXT STEP','<div class="cta"><h2>Enroll in the free course</h2><p data-cue="cta">Explore the lessons and run your first practical example.</p><small>LUIS COCO ENRIQUEZ</small></div>',[('cta','Enroll in the free course and run your first practical example. Thank you for watching.')])
add('Explore the learning platform','SEPARATE COURSE PREVIEW','<img class="full" src="platform.jpg"><div class="invisible" data-cue="platform" style="left:205px;top:50px;width:1410px;height:47px"></div>',[('platform','Continue learning with the full Claude Agent SDK course.')],'platform',{'file':f'presentations/{NAME}/platform-excerpt.mp4','rect':[0,0,1920,1080]})
metrics=''.join(f'<article class="metric"><div data-cue="{cid}"><strong>{number}</strong><h2>{label}</h2></div></article>' for cid,number,label in [('more-concepts','60','Concept lessons'),('more-apps','60','Practical example applications'),('more-labs','75','Hands-on labs')])
