 (V/'narration-plan.json').write_text(json.dumps({'project':NAME,'title':'Claude Agent SDK — Short Course Promo','mediaPrefix':'Claude-Agent-SDK-Short-Promo','outputFile':'Claude-Agent-SDK-Short-Promo.mp4','presentation':source.relative_to(ROOT).as_posix(),'presentationSha256':hashlib.sha256(source.read_bytes()).hexdigest(),'settings':SETTINGS,'slides':rows},indent=2))
 (V/'highlight-semantic-audit.json').write_text(json.dumps(audit,indent=2))
 print('12-scene narration plan ready.')
